// Crash-matrix results and their rendering (docs/generated/crash-matrix.{json,md}). Pure, unit-tested.
// The table is GENERATED by the suite (PRD: "make it a generated table, not a hand-written one").

export interface CrashResult {
  point: string;
  component: string;
  description: string;
  /** Events the test sent (acknowledged by Kafka). */
  sent: number;
  /** Records in Kafka beyond `sent` (a producer-side duplicate). */
  duplicatesProduced: number;
  /** Rows stored / offsets committed when the process died. */
  storedAtCrash: number;
  committedAtCrash: number;
  /** Records the restarted process wrote again and the sink absorbed (counted duplicates). */
  duplicatesProcessed: number;
  /** Stored rows beyond one per (tenant, event_id): must be 0. */
  duplicatesStored: number;
  /** Sent events missing from storage after recovery: must be 0. */
  lost: number;
  /** Restart to "every row stored and every offset committed". */
  recoveryMs: number;
  /** Process exit was a SIGKILL at this point (the crash really happened where intended). */
  crashed: boolean;
}

export interface CrashMatrix {
  generatedAt: string;
  commit: string;
  results: CrashResult[];
}

export const verdict = (r: CrashResult) => (r.crashed && r.lost === 0 && r.duplicatesStored === 0 ? 'ok' : 'FAIL');

export function renderMarkdown(m: CrashMatrix): string {
  const lines = [
    '# Crash matrix',
    '',
    `*Generated by \`tests/correctness/test/crash-matrix.e2e-spec.ts\` on ${m.generatedAt} at commit \`${m.commit}\`. Do not edit by hand: run \`pnpm --filter @eventpulse/correctness-tests crash-matrix\`.*`,
    '',
    'Each row: the process is SIGKILLed at the named point, restarted without the fault, and the pipeline is run to lag 0.',
    '"Processed again" = records the restarted process wrote a second time (absorbed by the sink and counted). "Stored twice" and "Lost" must be 0.',
    '',
    '| Crash point | What has happened at the crash | Sent | Dup. produced | Stored at crash | Committed at crash | Processed again | Stored twice | Lost | Recovery (ms) | Verdict |',
    '| --- | --- | ---: | ---: | ---: | ---: | ---: | ---: | ---: | ---: | --- |',
    ...m.results.map(
      (r) =>
        `| \`${r.point}\` | ${r.description} | ${r.sent} | ${r.duplicatesProduced} | ${r.storedAtCrash} | ${r.committedAtCrash} | ${r.duplicatesProcessed} | ${r.duplicatesStored} | ${r.lost} | ${r.recoveryMs} | ${verdict(r)} |`,
    ),
    '',
  ];
  return lines.join('\n');
}
